/* runtime/spu/spu_interp.c
 *
 * Runtime C interpreter for SPU code resident in a 256KB local store.
 * Decode is a verbatim port of tools/spu_disasm.py:spu_decode (field
 * extraction + 9-step priority order). Execute reuses spu_helpers.h and the
 * channel glue in spu_channels.c (spu_rdch/spu_wrch/spu_rchcnt).
 *
 * SPU LS is big-endian: instruction fetch uses spu_ls_read32 (explicit BE
 * assembly) and quadword data uses spu_ls_read128/write128 (per-word swap).
 *
 * FIX vs original design: the sub-decoder forward declarations MUST physically
 * precede spu_step (the original put them only in a trailing comment, which
 * would not compile). They are included inline below.
 */
#include "spu_context.h"
#include "spu_helpers.h"
#include "spu_dma.h"      /* type completeness; DMA reached via channels */
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Channel glue implemented in spu_channels.c */
u128     spu_rdch(spu_context* ctx, uint32_t channel);
void     spu_wrch(spu_context* ctx, uint32_t channel, u128 value);
uint32_t spu_rchcnt(spu_context* ctx, uint32_t channel);

/* ---- field-extraction helpers (mirror spu_disasm.py:310-324) ---- */
static inline int32_t spu_sext(uint32_t v, int nbits) {
    uint32_t m = 1u << (nbits - 1);
    return (int32_t)((v ^ m) - m);
}

/* register / LS / immediate access macros (the `ins` variable must be in scope) */
#define RT   (ins & 0x7F)
#define RA   ((ins >> 7) & 0x7F)
#define RB   ((ins >> 14) & 0x7F)
#define RC   ((ins >> 21) & 0x7F)             /* RRR third source */
#define G(i)   (ctx->gpr[(i) & 0x7F])         /* register cell (lvalue) */
#define AU32(i)(ctx->gpr[(i) & 0x7F]._u32[0]) /* preferred-slot address */
#define I7   ((int)((ins >> 14) & 0x7F))
#define I10  spu_sext((ins >> 14) & 0x3FF, 10)
#define I16  spu_sext((ins >> 7)  & 0xFFFF, 16)
#define I18  (((ins >> 7) & 0x3FFFF))
#define CHAN ((ins >> 7) & 0x1F)
#define U16  ((ins >> 7) & 0xFFFF)            /* unsigned i16 (ilh/ilhu/iohl/fsmbi) */

/* Running predicate + sub-decoder prototypes — declared BEFORE spu_step so the
 * single translation unit compiles regardless of definition order. */
static inline int spu_running(spu_context* c){ return c->status == SPU_STATUS_RUNNING; }
static int spu_decode_ri16(spu_context*, uint32_t ins, uint32_t op9, uint32_t pc, uint32_t* next);
static int spu_decode_ri10(spu_context*, uint32_t ins, uint32_t op8);
static int spu_decode_ri8 (spu_context*, uint32_t ins, uint32_t op10);
static int spu_decode_rr  (spu_context*, uint32_t ins, uint32_t op11, uint32_t pc, uint32_t* next, int* handled, int* stop);
static int spu_decode_ri7 (spu_context*, uint32_t ins, uint32_t op11);

static int spu_step(spu_context* ctx);

/* ---- public entry: run until the context leaves RUNNING ---- */
int spu_interpret(spu_context* ctx)
{
    ctx->status = SPU_STATUS_RUNNING;
    while (ctx->status == SPU_STATUS_RUNNING) {
        if (!spu_step(ctx))
            break;
    }
    return (int)ctx->status;
}

/* Optional single-step wrapper for debugging. */
int spu_interpret_step(spu_context* ctx)
{
    if (ctx->status != SPU_STATUS_RUNNING) ctx->status = SPU_STATUS_RUNNING;
    return spu_step(ctx);
}

/* Execute exactly one instruction at ctx->pc. Updates pc. */
static int spu_step(spu_context* ctx)
{
    uint32_t pc   = ctx->pc & SPU_LS_MASK;
    uint32_t ins  = spu_ls_read32(ctx, pc);     /* BE fetch */
    uint32_t next = (pc + 4) & SPU_LS_MASK;     /* default fallthrough */

    const uint32_t op4  = (ins >> 28) & 0xF;
    const uint32_t op7  = (ins >> 25) & 0x7F;
    const uint32_t op8  = (ins >> 24) & 0xFF;
    const uint32_t op9  = (ins >> 23) & 0x1FF;
    const uint32_t op10 = (ins >> 22) & 0x3FF;
    const uint32_t op11 = (ins >> 21) & 0x7FF;

    /* step 1: RRR (op4) */
    switch (op4) {
        case 0x8: G(RT) = spu_shufb(G(RA), G(RB), G(RC)); ctx->pc = next; return 1;
        case 0xB: G(RT) = spu_selb (G(RA), G(RB), G(RC)); ctx->pc = next; return 1;
        case 0xC: G(RT) = spu_mpya (G(RA), G(RB), G(RC)); ctx->pc = next; return 1;
        case 0xD: G(RT) = spu_fnms (G(RA), G(RB), G(RC)); ctx->pc = next; return 1;
        case 0xE: G(RT) = spu_fma  (G(RA), G(RB), G(RC)); ctx->pc = next; return 1;
        case 0xF: G(RT) = spu_fms  (G(RA), G(RB), G(RC)); ctx->pc = next; return 1;
        default: break;
    }

    /* step 2: RI18 (op7) */
    if (op7 == 0x21) { G(RT) = spu_ila(I18); ctx->pc = next; return 1; }   /* ila */
    if (op7 == 0x08 || op7 == 0x09) { ctx->pc = next; return 1; }          /* hbra/hbrr hint */

    /* step 3: RI16 (op9) — BEFORE RI10 */
    if (spu_decode_ri16(ctx, ins, op9, pc, &next)) { ctx->pc = next; return spu_running(ctx); }

    /* step 4: channel ops (op11) — BEFORE RI10 */
    if (op11 == 0x00D) { G(RT) = spu_rdch(ctx, CHAN); ctx->pc = next; return spu_running(ctx); }
    if (op11 == 0x10D) { spu_wrch(ctx, CHAN, G(RT)); ctx->pc = next; return spu_running(ctx); }
    if (op11 == 0x00F) { G(RT) = spu_splat_u32(spu_rchcnt(ctx, CHAN)); ctx->pc = next; return 1; }

    /* step 5: RI10 (op8) */
    if (spu_decode_ri10(ctx, ins, op8)) { ctx->pc = next; return 1; }

    /* step 6: RI8 (op10) float<->int conversions */
    if (spu_decode_ri8(ctx, ins, op10)) { ctx->pc = next; return 1; }

    /* step 7: RR (op11) — arith/logic/compare/shift + control + branches */
    {
        int handled = 0, stop = 0;
        if (spu_decode_rr(ctx, ins, op11, pc, &next, &handled, &stop)) {
            ctx->pc = next;
            return stop ? 0 : 1;
        }
        if (handled) { ctx->pc = next; return 1; }
    }

    /* step 8: RI7 (op11) shift/rotate immediates */
    if (spu_decode_ri7(ctx, ins, op11)) { ctx->pc = next; return 1; }

    /* step 9: lqx/stqx (op11) */
    if (op11 == 0x1C4) { G(RT) = spu_ls_read128(ctx, AU32(RA) + AU32(RB)); ctx->pc = next; return 1; }
    if (op11 == 0x144) { spu_ls_write128(ctx, AU32(RA) + AU32(RB), G(RT)); ctx->pc = next; return 1; }

    /* illegal/unimplemented -> halt so the bug is visible */
    ctx->status = SPU_STATUS_STOPPED_BY_HALT;
    return 0;
}

#ifdef __cplusplus
}
#endif
/* The sub-decoder DEFINITIONS (spu_decode_ri16/ri10/ri8/rr/ri7) follow in the
 * tier-1 handler block; they are part of this same .c file. */

tier1Handlers:
/* ===== Tier-1 sub-decoder DEFINITIONS — same translation unit as spu_step.
 * Place AFTER spu_step (prototypes are already declared above it). The
 * RT/RA/RB/RC/I*/G/AU32/CHAN/U16 macros remain in scope. Every ALU/shift/
 * compare op is one call into spu_helpers.h (all signatures compile-verified). */

/* ---- RI16 (op9): immediate loads, PC-rel/abs loads/stores, branches ---- */
static int spu_decode_ri16(spu_context* ctx, uint32_t ins, uint32_t op9,
                           uint32_t pc, uint32_t* next)
{
    switch (op9) {
    case 0x081: G(RT) = spu_il(I16);                      return 1; /* il (sign-ext) */
    case 0x082: G(RT) = spu_ilhu((uint16_t)U16);          return 1; /* ilhu */
    case 0x083: G(RT) = spu_ilh((uint16_t)U16);           return 1; /* ilh */
    case 0x0C1: G(RT) = spu_iohl(G(RT), (uint16_t)U16);   return 1; /* iohl */
    case 0x065: G(RT) = spu_fsmbi((int32_t)U16);          return 1; /* fsmbi */
    case 0x061: G(RT) = spu_ls_read128(ctx, (uint32_t)((I16 & 0x3FFF) << 4));  return 1; /* lqa */
    case 0x041: spu_ls_write128(ctx, (uint32_t)((I16 & 0x3FFF) << 4), G(RT));  return 1; /* stqa */
    case 0x067: G(RT) = spu_ls_read128(ctx, (uint32_t)(pc + I16 * 4));         return 1; /* lqr */
    case 0x047: spu_ls_write128(ctx, (uint32_t)(pc + I16 * 4), G(RT));         return 1; /* stqr */
    case 0x064: *next = (uint32_t)(pc + I16 * 4) & SPU_LS_MASK;      return 1; /* br */
    case 0x060: *next = (uint32_t)(I16 * 4)      & SPU_LS_MASK;      return 1; /* bra */
    case 0x066: G(RT) = spu_splat_u32((pc + 4) & SPU_LS_MASK);
                *next = (uint32_t)(pc + I16 * 4) & SPU_LS_MASK;      return 1; /* brsl */
    case 0x062: G(RT) = spu_splat_u32((pc + 4) & SPU_LS_MASK);
                *next = (uint32_t)(I16 * 4) & SPU_LS_MASK;           return 1; /* brasl */
    case 0x040: if (G(RT)._u32[0] == 0) *next = (uint32_t)(pc + I16*4) & SPU_LS_MASK; return 1; /* brz  */
    case 0x042: if (G(RT)._u32[0] != 0) *next = (uint32_t)(pc + I16*4) & SPU_LS_MASK; return 1; /* brnz */
    case 0x044: if (G(RT)._u16[1] == 0) *next = (uint32_t)(pc + I16*4) & SPU_LS_MASK; return 1; /* brhz */
    case 0x046: if (G(RT)._u16[1] != 0) *next = (uint32_t)(pc + I16*4) & SPU_LS_MASK; return 1; /* brhnz*/
    default: return 0;
    }
}

/* ---- RI10 (op8): arith/logic/compare immediates + lqd/stqd ---- */
static int spu_decode_ri10(spu_context* ctx, uint32_t ins, uint32_t op8)
{
    switch (op8) {
    case 0x34: G(RT) = spu_ls_read128(ctx, AU32(RA) + (uint32_t)(I10 << 4)); return 1; /* lqd */
    case 0x24: spu_ls_write128(ctx, AU32(RA) + (uint32_t)(I10 << 4), G(RT)); return 1; /* stqd */
    case 0x1C: G(RT) = spu_ai  (G(RA), I10); return 1;
    case 0x0C: G(RT) = spu_sfi (G(RA), I10); return 1;
    case 0x1D: G(RT) = spu_ahi (G(RA), I10); return 1;
    case 0x0D: G(RT) = spu_sfhi(G(RA), I10); return 1;
    case 0x14: G(RT) = spu_andi(G(RA), I10); return 1;
    case 0x04: G(RT) = spu_ori (G(RA), I10); return 1;
    case 0x05: G(RT) = spu_orhi(G(RA), I10); return 1;
    case 0x15: G(RT) = spu_andhi(G(RA), I10); return 1;
    case 0x16: G(RT) = spu_andbi(G(RA), I10); return 1;
    case 0x44: G(RT) = spu_xori(G(RA), I10); return 1;
    case 0x7C: G(RT) = spu_ceqi (G(RA), I10); return 1;
    case 0x7D: G(RT) = spu_ceqhi(G(RA), I10); return 1;
    case 0x7E: G(RT) = spu_ceqbi(G(RA), I10); return 1;
    case 0x4C: G(RT) = spu_cgti (G(RA), I10); return 1;
    case 0x4D: G(RT) = spu_cgthi(G(RA), I10); return 1;
    case 0x4E: G(RT) = spu_cgtbi(G(RA), I10); return 1;
    case 0x5C: G(RT) = spu_clgti (G(RA), I10); return 1;
    case 0x5D: G(RT) = spu_clgthi(G(RA), I10); return 1;
    case 0x5E: G(RT) = spu_clgtbi(G(RA), I10); return 1;
    case 0x74: G(RT) = spu_mpyi (G(RA), I10); return 1;
    case 0x75: G(RT) = spu_mpyui(G(RA), I10); return 1;
    default: return 0;
    }
}

/* ---- RI8 (op10): float<->int conversions (i8 = (ins>>14)&0xFF) ---- */
static int spu_decode_ri8(spu_context* ctx, uint32_t ins, uint32_t op10)
{
    int i8 = (int)((ins >> 14) & 0xFF);
    switch (op10) {
    case 0x1D8: G(RT) = spu_cflts(G(RA), i8); return 1;
    case 0x1D9: G(RT) = spu_cfltu(G(RA), i8); return 1;
    case 0x1DA: G(RT) = spu_csflt(G(RA), i8); return 1;
    case 0x1DB: G(RT) = spu_cuflt(G(RA), i8); return 1;
    default: return 0;
    }
}

/* ---- RI7 (op11): shift/rotate-by-immediate; i7 = bits 14-20 ---- */
static int spu_decode_ri7(spu_context* ctx, uint32_t ins, uint32_t op11)
{
    int i7 = I7;
    switch (op11) {
    case 0x078: G(RT) = spu_roti  (G(RA), i7); return 1;
    case 0x079: G(RT) = spu_rotmi (G(RA), i7); return 1;
    case 0x07A: G(RT) = spu_rotmai(G(RA), i7); return 1;
    case 0x07B: G(RT) = spu_shli  (G(RA), i7); return 1;
    case 0x07C: G(RT) = spu_rothi (G(RA), i7); return 1;
    case 0x07D: G(RT) = spu_rothmi(G(RA), i7); return 1;
    case 0x07E: G(RT) = spu_rotmahi(G(RA), i7); return 1;
    case 0x07F: G(RT) = spu_shlhi (G(RA), i7); return 1;
    case 0x1F8: G(RT) = spu_rotqbii (G(RA), i7); return 1;
    case 0x1F9: G(RT) = spu_rotqmbii(G(RA), i7); return 1;
    case 0x1FB: G(RT) = spu_shlqbii (G(RA), i7); return 1;
    case 0x1FC: G(RT) = spu_rotqbyi (G(RA), i7); return 1;
    case 0x1FD: G(RT) = spu_rotqmbyi(G(RA), i7); return 1;
    case 0x1FF: G(RT) = spu_shlqbyi (G(RA), i7); return 1;
    default: return 0;
    }
}

/* ---- RR (op11): arith/logic/compare/shift-reg + control + branches ----
 * Return 1 if *next was set (branch/stop). *handled=1 for plain ALU ops.
 * *stop=1 ends the run. */
static int spu_decode_rr(spu_context* ctx, uint32_t ins, uint32_t op11,
                         uint32_t pc, uint32_t* next, int* handled, int* stop)
{
    *handled = 0; *stop = 0;
    switch (op11) {
    /* control */
    case 0x000: ctx->srr0 = ins & 0x3FFF; ctx->status = SPU_STATUS_STOPPED_BY_STOP;
                *stop = 1; *next = (pc+4)&SPU_LS_MASK; return 1;            /* stop */
    case 0x140: ctx->status = SPU_STATUS_STOPPED_BY_STOP;
                *stop = 1; *next = (pc+4)&SPU_LS_MASK; return 1;            /* stopd */
    case 0x001: case 0x201: case 0x002: case 0x003:                        /* lnop/nop/sync/dsync */
                *handled = 1; return 0;
    /* arith */
    case 0x0C0: G(RT)=spu_a  (G(RA),G(RB)); *handled=1; return 0;
    case 0x040: G(RT)=spu_sf (G(RA),G(RB)); *handled=1; return 0;
    case 0x0C8: G(RT)=spu_ah (G(RA),G(RB)); *handled=1; return 0;
    case 0x048: G(RT)=spu_sfh(G(RA),G(RB)); *handled=1; return 0;
    case 0x0C2: G(RT)=spu_cg (G(RA),G(RB)); *handled=1; return 0;
    case 0x340: G(RT)=spu_addx(G(RA),G(RB),G(RT)); *handled=1; return 0;    /* rt is src */
    case 0x341: G(RT)=spu_sfx (G(RA),G(RB),G(RT)); *handled=1; return 0;
    case 0x3C4: G(RT)=spu_mpy (G(RA),G(RB)); *handled=1; return 0;
    case 0x3C5: G(RT)=spu_mpyh(G(RA),G(RB)); *handled=1; return 0;
    case 0x3C6: G(RT)=spu_mpyhh(G(RA),G(RB)); *handled=1; return 0;
    case 0x3C7: G(RT)=spu_mpys(G(RA),G(RB)); *handled=1; return 0;
    case 0x3CC: G(RT)=spu_mpyu(G(RA),G(RB)); *handled=1; return 0;
    /* NOTE: bg op11=0x042 collides with brnz op9=0x042 only by VALUE not by
     * decode-step — bg is reached only here in step 7 (RI16 step 3 already
     * consumed any op9==0x042). Safe. */
    case 0x042: G(RT)=spu_bg (G(RA),G(RB)); *handled=1; return 0;           /* bg */
    /* logic */
    case 0x041: G(RT)=spu_or  (G(RA),G(RB)); *handled=1; return 0;          /* (op9 0x041=stqa handled in step3) */
    case 0x0C1: G(RT)=spu_and (G(RA),G(RB)); *handled=1; return 0;
    case 0x241: G(RT)=spu_xor (G(RA),G(RB)); *handled=1; return 0;
    case 0x0C9: G(RT)=spu_nand(G(RA),G(RB)); *handled=1; return 0;
    case 0x049: G(RT)=spu_nor (G(RA),G(RB)); *handled=1; return 0;
    case 0x2C1: G(RT)=spu_andc(G(RA),G(RB)); *handled=1; return 0;
    case 0x2C9: G(RT)=spu_orc (G(RA),G(RB)); *handled=1; return 0;
    /* compares */
    case 0x3C0: G(RT)=spu_ceq (G(RA),G(RB)); *handled=1; return 0;
    case 0x3C8: G(RT)=spu_ceqh(G(RA),G(RB)); *handled=1; return 0;
    case 0x3D0: G(RT)=spu_ceqb(G(RA),G(RB)); *handled=1; return 0;
    case 0x240: G(RT)=spu_cgt (G(RA),G(RB)); *handled=1; return 0;
    case 0x248: G(RT)=spu_cgth(G(RA),G(RB)); *handled=1; return 0;
    case 0x250: G(RT)=spu_cgtb(G(RA),G(RB)); *handled=1; return 0;
    case 0x2C0: G(RT)=spu_clgt (G(RA),G(RB)); *handled=1; return 0;
    case 0x2C8: G(RT)=spu_clgth(G(RA),G(RB)); *handled=1; return 0;
    case 0x2D0: G(RT)=spu_clgtb(G(RA),G(RB)); *handled=1; return 0;
    /* register-variable shifts/rotates */
    case 0x058: G(RT)=spu_rot (G(RA),G(RB)); *handled=1; return 0;
    case 0x059: G(RT)=spu_rotm(G(RA),G(RB)); *handled=1; return 0;
    case 0x05A: G(RT)=spu_rotma(G(RA),G(RB)); *handled=1; return 0;
    case 0x05B: G(RT)=spu_shl (G(RA),G(RB)); *handled=1; return 0;
    case 0x05C: G(RT)=spu_roth(G(RA),G(RB)); *handled=1; return 0;
    case 0x05D: G(RT)=spu_rothm(G(RA),G(RB)); *handled=1; return 0;
    case 0x05F: G(RT)=spu_shlh(G(RA),G(RB)); *handled=1; return 0;
    case 0x1CC: G(RT)=spu_rotqbybi (G(RA),G(RB)); *handled=1; return 0;
    case 0x1CD: G(RT)=spu_rotqmbybi(G(RA),G(RB)); *handled=1; return 0;
    case 0x1CF: G(RT)=spu_shlqbybi (G(RA),G(RB)); *handled=1; return 0;
    case 0x1D8: G(RT)=spu_rotqbi (G(RA),G(RB)); *handled=1; return 0;
    case 0x1D9: G(RT)=spu_rotqmbi(G(RA),G(RB)); *handled=1; return 0;
    case 0x1DB: G(RT)=spu_shlqbi (G(RA),G(RB)); *handled=1; return 0;
    case 0x1DC: G(RT)=spu_rotqby (G(RA),G(RB)); *handled=1; return 0;
    case 0x1DD: G(RT)=spu_rotqmby(G(RA),G(RB)); *handled=1; return 0;
    case 0x1DF: G(RT)=spu_shlqby (G(RA),G(RB)); *handled=1; return 0;
    /* unary */
    case 0x2A5: G(RT)=spu_clz (G(RA)); *handled=1; return 0;
    case 0x2B4: G(RT)=spu_cntb(G(RA)); *handled=1; return 0;
    case 0x2B6: G(RT)=spu_xsbh(G(RA)); *handled=1; return 0;
    case 0x2AE: G(RT)=spu_xshw(G(RA)); *handled=1; return 0;
    case 0x2A6: G(RT)=spu_xswd(G(RA)); *handled=1; return 0;
    case 0x1B0: G(RT)=spu_gb  (G(RA)); *handled=1; return 0;
    case 0x1B1: G(RT)=spu_gbh (G(RA)); *handled=1; return 0;
    case 0x1F0: G(RT)=spu_orx (G(RA)); *handled=1; return 0;
    case 0x1B4: G(RT)=spu_fsm (G(RA)); *handled=1; return 0;
    case 0x1B5: G(RT)=spu_fsmh(G(RA)); *handled=1; return 0;
    case 0x1B6: G(RT)=spu_fsmb(G(RA)); *handled=1; return 0;
    /* register-indirect branches. Disasm: bi/bisl op = "$rA" (ops[0]=RA=target);
     * biz/binz/bihz/bihnz = "$rt, $rA" (RT=cond reg, RA=target reg). */
    case 0x1A8: /* bi $rA : SPU ABI $r0 = link; bi $r0 = OS-level return */
        if (RA == 0) { ctx->status = SPU_STATUS_STOPPED; *stop = 1; *next = (pc+4)&SPU_LS_MASK; return 1; }
        *next = AU32(RA) & SPU_LS_MASK; return 1;
    case 0x1AA: *next = ctx->srr0 & SPU_LS_MASK; return 1;                  /* iret */
    case 0x1A9: G(RT) = spu_splat_u32((pc + 4) & SPU_LS_MASK);
                *next = AU32(RA) & SPU_LS_MASK; return 1;                   /* bisl */
    case 0x128: if (G(RT)._u32[0] == 0) *next = AU32(RA) & SPU_LS_MASK; return 1; /* biz   */
    case 0x129: if (G(RT)._u32[0] != 0) *next = AU32(RA) & SPU_LS_MASK; return 1; /* binz  */
    case 0x12A: if (G(RT)._u16[1] == 0) *next = AU32(RA) & SPU_LS_MASK; return 1; /* bihz  */
    case 0x12B: if (G(RT)._u16[1] != 0) *next = AU32(RA) & SPU_LS_MASK; return 1; /* bihnz */
    case 0x1AC: *handled = 1; return 0;                                    /* hbr hint */
    default: return 0;
    }
}

test:
Standalone harness modeled on runtime/spu/tests. It links the REAL spu_channels.c so wrch routes MFC + mailbox correctly. The program is hand-assembled big-endian into ctx.ls.

FILE: runtime/spu/tests/test_interp_main.c
----------------------------------------------------------------
#include "spu_context.h"
#include "spu_helpers.h"
#include "spu_dma.h"
#include <stdio.h>
#include <stddef.h>
#include <stdint.h>

/* DMA backing memory (spu_dma.h dereferences vm_base + (uint32_t)ea). */
static uint8_t g_mem[4096];
uint8_t* vm_base = g_mem;

int spu_interpret(spu_context* ctx);   /* from runtime/spu/spu_interp.c */

/* big-endian word store into LS */
static void w(uint8_t* p, uint32_t v){ p[0]=(uint8_t)(v>>24);p[1]=(uint8_t)(v>>16);p[2]=(uint8_t)(v>>8);p[3]=(uint8_t)v; }
/* encoders (bit layout matches spu_disasm.py field extraction) */
static uint32_t e_ri16(uint32_t op9,uint32_t i16,uint32_t rt){return ((op9&0x1FF)<<23)|((i16&0xFFFF)<<7)|(rt&0x7F);}
static uint32_t e_ri10(uint32_t op8,int i10,uint32_t ra,uint32_t rt){return ((op8&0xFF)<<24)|(((uint32_t)i10&0x3FF)<<14)|((ra&0x7F)<<7)|(rt&0x7F);}
static uint32_t e_rr (uint32_t op11,uint32_t rb,uint32_t ra,uint32_t rt){return ((op11&0x7FF)<<21)|((rb&0x7F)<<14)|((ra&0x7F)<<7)|(rt&0x7F);}
static uint32_t e_ch (uint32_t op11,uint32_t chn,uint32_t rt){return ((op11&0x7FF)<<21)|((chn&0x1F)<<7)|(rt&0x7F);}

int main(void){
    spu_context ctx; spu_context_init(&ctx,0);

    /* Program (PCs in comments):
     * 00 il   r3,7
     * 04 il   r4,35
     * 08 a    r5,r3,r4         ; r5 = 42
     * 0C il   r6,0x200
     * 10 stqd r5,0(r6)         ; LS[0x200] = 42 (preferred word)
     * 14 ai   r4,r4,-1
     * 18 brnz r4,0x14          ; loop until r4==0  (i16 = -1)
     * 1C il   r7,0x100         ; MFC_LSA
     * 20 wrch MFC_LSA(16),r7
     * 24 il   r8,0
     * 28 wrch MFC_EAL(18),r8
     * 2C wrch MFC_EAH(17),r8
     * 30 il   r9,4
     * 34 wrch MFC_Size(19),r9
     * 38 il   r9,0
     * 3C wrch MFC_TagID(20),r9
     * 40 il   r9,0x40          ; MFC_GET_CMD
     * 44 wrch MFC_Cmd(21),r9   ; synchronous GET
     * 48 wrch SPU_WrOutMbox(28),r5  ; mailbox <- 42
     * 4C stop
     */
    uint32_t prog[] = {
        e_ri16(0x081, 7, 3),
        e_ri16(0x081, 35, 4),
        e_rr  (0x0C0, 4, 3, 5),
        e_ri16(0x081, 0x200, 6),
        e_ri10(0x24, 0, 6, 5),
        e_ri10(0x1C, -1, 4, 4),
        e_ri16(0x042, 0xFFFF, 4),     /* brnz r4, pc-4 : (-1)*4 + 0x18 = 0x14 */
        e_ri16(0x081, 0x100, 7),
        e_ch  (0x10D, 16, 7),
        e_ri16(0x081, 0, 8),
        e_ch  (0x10D, 18, 8),
        e_ch  (0x10D, 17, 8),
        e_ri16(0x081, 4, 9),
        e_ch  (0x10D, 19, 9),
        e_ri16(0x081, 0, 9),
        e_ch  (0x10D, 20, 9),
        e_ri16(0x081, 0x40, 9),
        e_ch  (0x10D, 21, 9),
        e_ch  (0x10D, 28, 5),
        e_rr  (0x000, 0, 0, 0),
    };
    for (size_t i=0;i<sizeof(prog)/4;i++) w(&ctx.ls[i*4], prog[i]);

    /* main-memory pattern the GET copies into LS[0x100] */
    g_mem[0]=0xDE; g_mem[1]=0xAD; g_mem[2]=0xBE; g_mem[3]=0xEF;

    ctx.pc = 0;
    spu_interpret(&ctx);

    int ok = 1;
    if (ctx.gpr[5]._u32[0] != 42){ printf("FAIL r5=%u\n",ctx.gpr[5]._u32[0]); ok=0; }
    if (spu_ls_read32(&ctx,0x200) != 42){ printf("FAIL LS[0x200]=0x%08X\n",spu_ls_read32(&ctx,0x200)); ok=0; }
    /* DMA path is a raw memcpy in mfc_do_transfer; read32 reassembles BE -> 0xDEADBEEF */
    if (spu_ls_read32(&ctx,0x100) != 0xDEADBEEFu){ printf("FAIL LS[0x100]=0x%08X\n",spu_ls_read32(&ctx,0x100)); ok=0; }
    if (!spu_channel_has_data(&ctx.ch_out_mbox) || ctx.ch_out_mbox.value != 42){ printf("FAIL mbox=%u\n",ctx.ch_out_mbox.value); ok=0; }
    if (ctx.status != SPU_STATUS_STOPPED_BY_STOP){ printf("FAIL status=0x%X\n",ctx.status); ok=0; }

    printf(ok ? "[PASS] interp: r5=42 LS[0x200]=42 LS[0x100]=DEADBEEF mbox=42\n" : "[FAIL] interp\n");
    return ok ? 0 : 1;
}
